def swap_first_last_char(text: str) -> str:
    if len(text) < 2:
        return text
    return text[-1] + text[1:-1] + text[0]

def alternate_letter_case(text: str) -> str:
    out = []
    upper = True
    for ch in text:
        if ch.isalpha():
            out.append(ch.upper() if upper else ch.lower())
            upper = not upper
        else:
            out.append(ch)
    return "".join(out)

def longest_vowel_run(text: str) -> int:
    best = current = 0
    for ch in text:
        if ch.lower() in "aeiou":
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best

def collapse_repeated_chars(text: str) -> str:
    out = []
    for ch in text:
        if not out or out[-1] != ch:
            out.append(ch)
    return "".join(out)

def first_repeated_char(text: str) -> str:
    seen = set()
    for ch in text:
        if ch in seen:
            return ch
        seen.add(ch)
    return ""

def mask_all_but_last_four(text: str, mask_char: str = "#") -> str:
    hidden = max(len(text) - 4, 0)
    return mask_char * hidden + text[hidden:]

def snake_to_camel_case(name: str) -> str:
    parts = [p for p in name.split("_") if p]
    if not parts:
        return ""
    return parts[0] + "".join(p[0].upper() + p[1:] for p in parts[1:])

def most_frequent_char(text: str) -> str:
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    best = ""
    for ch, n in counts.items():
        if best == "" or n > counts[best]:
            best = ch
    return best

def count_words_starting_with(sentence: str, letter: str) -> int:
    target = letter.lower()
    return sum(1 for word in sentence.split() if word[0].lower() == target)

def keep_alphanumeric_only(text: str) -> str:
    import string

    allowed = set(string.ascii_letters + string.digits)
    return "".join(ch for ch in text if ch in allowed)

def run_length_encode_compact(text: str) -> str:
    from itertools import groupby

    parts = []
    for ch, group in groupby(text):
        n = sum(1 for _ in group)
        parts.append(ch if n == 1 else f"{ch}{n}")
    return "".join(parts)

def shift_letters_by(text: str, shift: int) -> str:
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + shift) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + shift) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)

