def first_occurrence_signature(text: str) -> List[int]:
    ids = {}
    return [ids.setdefault(ch, len(ids)) for ch in text]

def same_letter_pattern(first: str, second: str) -> bool:
    if len(first) != len(second):
        return False
    forward, backward = {}, {}
    for a, b in zip(first, second):
        if forward.setdefault(a, b) != b or backward.setdefault(b, a) != a:
            return False
    return True

def normalize_spacing(text: str) -> str:
    collapsed = " ".join(text.split())
    out = []
    for ch in collapsed:
        if ch in ",.!?;:" and out and out[-1] == " ":
            out.pop()
        out.append(ch)
    return "".join(out)

