def headline_case(title: str, minor_words: Iterable[str] = ("a", "an", "the", "of", "and", "or", "in", "on", "to")) -> str:
    minor = {w.lower() for w in minor_words}
    words = title.lower().split()
    out = []
    for i, word in enumerate(words):
        if i == 0 or i == len(words) - 1 or word not in minor:
            out.append(word[:1].upper() + word[1:])
        else:
            out.append(word)
    return " ".join(out)

