def longest_common_suffix(words: List[str]) -> str:
    if not words:
        return ""
    shortest = min(len(w) for w in words)
    k = 0
    while k < shortest and len({w[len(w) - 1 - k] for w in words}) == 1:
        k += 1
    return words[0][len(words[0]) - k:]

def interleave_strings(left: str, right: str) -> str:
    from itertools import zip_longest

    return "".join(a + b for a, b in zip_longest(left, right, fillvalue=""))

def vowel_consonant_difference(text: str) -> int:
    total = 0
    for ch in text.lower():
        if "a" <= ch <= "z":
            total += 1 if ch in "aeiou" else -1
    return total

from typing import List, Tuple


def character_runs(text: str) -> List[Tuple[str, int]]:
    runs: List[Tuple[str, int]] = []
    for ch in text:
        if runs and runs[-1][0] == ch:
            runs[-1] = (ch, runs[-1][1] + 1)
        else:
            runs.append((ch, 1))
    return runs

def camel_to_snake_case(name: str) -> str:
    out = []
    for i, ch in enumerate(name):
        if "A" <= ch <= "Z":
            if i > 0:
                out.append("_")
            out.append(ch.lower())
        else:
            out.append(ch)
    return "".join(out)

