def count_anagram_classes(words: List[str]) -> int:
    return len({"".join(sorted(word.lower())) for word in words})

def smallest_rotation(text: str) -> str:
    if not text:
        return ""
    doubled = text + text
    n = len(text)
    return min(doubled[i:i + n] for i in range(n))

