def wrap_words_to_width(text: str, width: int) -> List[str]:
    lines: List[str] = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

def expand_char_ranges(spec: str) -> str:
    out = []
    i = 0
    n = len(spec)
    while i < n:
        if i + 2 < n and spec[i + 1] == "-" and spec[i] <= spec[i + 2]:
            out.extend(chr(c) for c in range(ord(spec[i]), ord(spec[i + 2]) + 1))
            i += 3
        else:
            out.append(spec[i])
            i += 1
    return "".join(out)

def max_distinct_in_window(text: str, window: int) -> int:
    if window < 1 or window > len(text):
        return 0
    counts = {}
    best = 0
    for i, ch in enumerate(text):
        counts[ch] = counts.get(ch, 0) + 1
        if i >= window:
            old = text[i - window]
            counts[old] -= 1
            if counts[old] == 0:
                del counts[old]
        if i >= window - 1:
            best = max(best, len(counts))
    return best

def longest_k_distinct_substring(text: str, k: int) -> str:
    if k <= 0:
        return ""
    counts = {}
    left = 0
    best_start, best_len = 0, 0
    for right, ch in enumerate(text):
        counts[ch] = counts.get(ch, 0) + 1
        while len(counts) > k:
            old = text[left]
            counts[old] -= 1
            if counts[old] == 0:
                del counts[old]
            left += 1
        if right - left + 1 > best_len:
            best_start, best_len = left, right - left + 1
    return text[best_start:best_start + best_len]

def edit_distance_with_transpositions(source: str, target: str) -> int:
    m, n = len(source), len(target)
    dist = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dist[i][0] = i
    for j in range(n + 1):
        dist[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if source[i - 1] == target[j - 1] else 1
            dist[i][j] = min(
                dist[i - 1][j] + 1,
                dist[i][j - 1] + 1,
                dist[i - 1][j - 1] + cost,
            )
            if (i > 1 and j > 1 and source[i - 1] == target[j - 2]
                    and source[i - 2] == target[j - 1]):
                dist[i][j] = min(dist[i][j], dist[i - 2][j - 2] + 1)
    return dist[m][n]

def shortest_palindrome_by_appending(text: str) -> str:
    rev = text[::-1]
    combined = rev + "\x00" + text
    fail = [0] * len(combined)
    for i in range(1, len(combined)):
        k = fail[i - 1]
        while k and combined[i] != combined[k]:
            k = fail[k - 1]
        if combined[i] == combined[k]:
            k += 1
        fail[i] = k
    longest_pal_suffix = fail[-1] if combined else 0
    return text + rev[longest_pal_suffix:]

def longest_repeated_substring(text: str) -> str:
    def find_repeat(length):
        seen = {}
        best = None
        for i in range(len(text) - length + 1):
            piece = text[i:i + length]
            if piece in seen:
                first = seen[piece]
                if best is None or first < best:
                    best = first
            else:
                seen[piece] = i
        return best

    lo, hi = 1, len(text) - 1
    best_start, best_len = 0, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        start = find_repeat(mid)
        if start is not None:
            best_start, best_len = start, mid
            lo = mid + 1
        else:
            hi = mid - 1
    return text[best_start:best_start + best_len]

