def shortest_unique_prefixes(words: List[str]) -> List[str]:
    counts = {}
    for word in words:
        for i in range(1, len(word) + 1):
            prefix = word[:i]
            counts[prefix] = counts.get(prefix, 0) + 1
    result = []
    for word in words:
        chosen = word
        for i in range(1, len(word) + 1):
            if counts[word[:i]] == 1:
                chosen = word[:i]
                break
        result.append(chosen)
    return result

def min_insertions_to_palindrome(text: str) -> int:
    n = len(text)
    if n == 0:
        return 0
    rev = text[::-1]
    prev = [0] * (n + 1)
    for i in range(1, n + 1):
        cur = [0] * (n + 1)
        for j in range(1, n + 1):
            if text[i - 1] == rev[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = max(prev[j], cur[j - 1])
        prev = cur
    return n - prev[n]

def smallest_no_adjacent_repeat(text: str) -> str:
    from collections import Counter

    counts = Counter(text)

    def feasible(last, remaining):
        if remaining == 0:
            return True
        limit = (remaining + 1) // 2
        for ch, c in counts.items():
            if c > limit:
                return False
            if remaining % 2 == 1 and c == limit and ch == last:
                return False
        return True

    if not feasible("", len(text)):
        return ""
    out = []
    last = ""
    for remaining in range(len(text), 0, -1):
        for ch in sorted(counts):
            if counts[ch] == 0 or ch == last:
                continue
            counts[ch] -= 1
            if feasible(ch, remaining - 1):
                out.append(ch)
                last = ch
                break
            counts[ch] += 1
    return "".join(out)

def kth_distinct_permutation(text: str, k: int) -> str:
    from collections import Counter
    from math import factorial

    counts = Counter(text)

    def arrangements(n):
        total = factorial(n)
        for c in counts.values():
            total //= factorial(c)
        return total

    n = len(text)
    if k < 1 or k > arrangements(n):
        return ""
    out = []
    for remaining in range(n, 0, -1):
        for ch in sorted(counts):
            if counts[ch] == 0:
                continue
            counts[ch] -= 1
            block = arrangements(remaining - 1)
            if k <= block:
                out.append(ch)
                break
            k -= block
            counts[ch] += 1
    return "".join(out)
